import{behaviorWeight}from './behavior.js';
import{memoryInfluence}from './life-state.js';
export function decisionUid(s){if(!s.pending)return null;s.pending.uid??=`${s.lifeId}:${s.pending.id}:${s.day}:${s.log.length}`;return s.pending.uid;}
export const actionWeight=behaviorWeight;
export function automaticAction(s,random){const options=s.pending?.options;if(!options?.length)return null;const weights=options.map(o=>actionWeight(s,o));let n=random(s)*weights.reduce((a,b)=>a+b,0);for(let i=0;i<options.length;i++){n-=weights[i];if(n<=0)return options[i].id}return options.at(-1).id;}
export function eventKind(id){if(id.startsWith('journey-'))return '경험';if(['birth','newborn','nursing','eyes','ears','walking','weaning','litter-play','first-food','growing-body','maturity'].includes(id))return '성장';if(/illness|vet|death|needs-warning|clinical|surgery|conservative|preventive|health-check/.test(id))return '건강';if(/adopt|adoption|placement|shop-|guardian-|rescued|shelter-return|found-intake|owner-|foster-|identity-|moving|settled|reunion|aging|birthday/.test(id))return '전환';if(/companion|child-|parent-care|litter-|pregnancy|reproduction|heat-cycle|neuter/.test(id))return /pregnancy|litter-born|child-departure|neuter/.test(id)?'전환':'관계';if(/dog|friend|relationship|encounter/.test(id))return '관계';if(/world|household|resource/.test(id))return '환경';if(id==='decision'||id==='choice'||id==='decision-outcome')return '선택';return '일상';}
export function importantRecords(s){return s.log.filter(e=>!['choice','decision'].includes(e.id)&&eventKind(e.id)!=='일상').slice(-2).reverse();}
export function currentSituation(s){if(!s.alive)return s.log.at(-1)?.text||'이 삶이 끝났다.';if(s.pending)return s.pending.text;if(s.presentation&&s.day-s.presentation.day<3)return s.presentation.text;const e=[...s.log].reverse().find(e=>!['choice','decision','birthday'].includes(e.id));if(e&&s.day-e.day<3)return e.text;if(s.reproduction?.pregnancy?.carrier==='self')return '몸이 묵직해져 쉬는 시간을 더 갖는다. 먹이와 물 가까운 조용한 자리에서 몸을 낮춘다.';if(s.reproduction?.children?.some(c=>c.present))return '새끼들의 작은 소리와 움직임이 가까운 잠자리에서 이어진다. 먹고 쉬며 각자의 거리를 조절한다.';if(s.clinical?.active)return '몸의 불편 때문에 움직임을 줄여 쉬고 있다. 먹이와 물 가까운 자리에서 상태에 맞춰 생활한다.';if(s.medical.episode)return '먹는 양과 움직임이 줄어 잠자리에서 쉬고 있다. 몸의 변화를 살피는 시간이 이어진다.';if(s.day<20)return s.worldModel.origin.mother?'어미와 몸을 맞대고 젖을 먹은 뒤 잠든다. 아직 잠자리 밖으로 나가지 못한다.':'돌보는 손길에 기대 먹고 잠든다. 따뜻한 잠자리 안에서 작은 몸을 움직인다.';if(s.day<55)return '낮은 그릇과 잠자리 사이를 오간다. 먹고 몸을 움직인 뒤에는 다시 오래 잠든다.';if(s.needs.thirst>75)return '움직임을 줄이고 물을 마실 자리를 찾고 있다.';if(s.home==='family')return '함께 사는 사람의 발소리를 듣다가 편한 자리에 눕는다. 물과 잠자리가 있는 방에서 몸을 쉰다.';if(s.home==='shelter')return '칸 안에서 물을 마시고 담요를 모아 눕는다. 복도에서 돌보는 사람의 발소리가 오간다.';return '늘 움직이던 구역 안에서 먹이와 물을 찾고, 사람이 붐비는 길에서는 비켜 쉰다.';}
